x_938076_backup_0_backup_scripts.script:
updateReason();

function updateReason() {
    WPLogger.info('Update Reason in Block Location', 'Starting upgrade script to update reason in Block Location.');

    var blockLocationGr = new GlideRecord(WPConstants.TABLES.BLOCK_LOCATION);
    blockLocationGr.addQuery("reason", "maintanance");
    blockLocationGr.query();
    while (blockLocationGr.next()) {
        blockLocationGr.reason = WPConstants.BLC_LOC_REASON.MAINTENANCE;
        blockLocationGr.update();
    }

    WPLogger.info('Update Reason in Block Location', 'Finishing upgrade script to update reason in Block Location.');
}
